CREATE TABLE audiences (id uuid PRIMARY KEY, org_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, description text, filter jsonb NOT NULL, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audiences_org_name_idx ON audiences (org_id, name); ALTER TABLE audiences ENABLE ROW LEVEL SECURITY; CREATE POLICY audiences_isolation_by_org ON audiences FOR ALL TO app_user USING (org_id = current_setting('app.current_org_id', true)::uuid);
CREATE TABLE campaigns (id uuid PRIMARY KEY, org_id uuid NOT NULL REFERENCES organizations(id), audience_id uuid NOT NULL REFERENCES audiences(id), name text NOT NULL, subject text NOT NULL, body text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','sending','sent','partial','failed')), recipient_count integer NOT NULL DEFAULT 0, sent_count integer NOT NULL DEFAULT 0, failed_count integer NOT NULL DEFAULT 0, suppressed_count integer NOT NULL DEFAULT 0, created_by uuid NOT NULL REFERENCES users(id), sent_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX campaigns_org_status_idx ON campaigns (org_id, status); ALTER TABLE campaigns ENABLE ROW LEVEL SECURITY; CREATE POLICY campaigns_isolation_by_org ON campaigns FOR ALL TO app_user USING (org_id = current_setting('app.current_org_id', true)::uuid);
CREATE TABLE campaign_recipients (id uuid PRIMARY KEY, org_id uuid NOT NULL REFERENCES organizations(id), campaign_id uuid NOT NULL REFERENCES campaigns(id) ON DELETE CASCADE, contact_id uuid NOT NULL REFERENCES contacts(id), email text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','sent','suppressed','failed')), provider_message_id text, error text, sent_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX campaign_recipients_campaign_contact_uidx ON campaign_recipients (campaign_id, contact_id); CREATE INDEX campaign_recipients_org_status_idx ON campaign_recipients (org_id, status); ALTER TABLE campaign_recipients ENABLE ROW LEVEL SECURITY; CREATE POLICY campaign_recipients_isolation_by_org ON campaign_recipients FOR ALL TO app_user USING (org_id = current_setting('app.current_org_id', true)::uuid);
CREATE TABLE email_suppressions (id uuid PRIMARY KEY, org_id uuid NOT NULL REFERENCES organizations(id), email text NOT NULL, reason text NOT NULL, source text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX email_suppressions_org_email_uidx ON email_suppressions (org_id, email); ALTER TABLE email_suppressions ENABLE ROW LEVEL SECURITY; CREATE POLICY email_suppressions_isolation_by_org ON email_suppressions FOR ALL TO app_user USING (org_id = current_setting('app.current_org_id', true)::uuid);
GRANT SELECT, INSERT, UPDATE, DELETE ON audiences, campaigns, campaign_recipients, email_suppressions TO app_user;
ALTER PUBLICATION electric_publication_default ADD TABLE audiences, campaigns, campaign_recipients;
UPDATE permission_groups SET capabilities = capabilities || '["campaigns:read", "campaigns:write"]'::jsonb, updated_at = now() WHERE name IN ('Proprietário','Administrador','Gerente','Agente') AND NOT capabilities @> '["campaigns:read", "campaigns:write"]'::jsonb;
UPDATE permission_groups SET capabilities = capabilities || '["campaigns:read"]'::jsonb, updated_at = now() WHERE name = 'Visualizador' AND NOT capabilities @> '["campaigns:read"]'::jsonb;
